/**
 * Normalize a customer booking verification code by trimming whitespace,
 * stripping leading hashes, removing internal spaces, and uppercasing.
 *
 * @param {string | null | undefined} raw
 * @returns {string}
 */
export function normalizeVerificationCode(raw) {
  return String(raw || '')
    .trim()
    .replace(/^#+/, '')
    .replace(/\s+/g, '')
    .toUpperCase();
}

/**
 * Validate whether a normalized verification code matches the formats
 * generated by the backend (e.g. CC-ESNNSR, CC-00001, CC-KEF-ABCDEF, or 6-char suffix ESNNSR).
 *
 * @param {string | null | undefined} raw
 * @returns {boolean}
 */
export function isValidVerificationCode(raw) {
  const code = normalizeVerificationCode(raw);
  if (!code || code.length > 24) return false;
  if (!/^[A-Z0-9]+(?:-[A-Z0-9]+)*$/.test(code)) return false;
  const alnumCount = code.replace(/-/g, '').length;
  return alnumCount >= 6;
}

/**
 * Extract the most specific user-facing message from an ApiError or Axios error.
 *
 * @param {any} err
 * @param {string} fallback
 * @returns {string}
 */
export function extractVerificationError(err, fallback = 'Failed to verify booking') {
  return (
    err?.details?.field_errors?.verification_code?.[0] ||
    err?.response?.data?.errors?.verification_code?.[0] ||
    err?.response?.data?.error?.details?.field_errors?.verification_code?.[0] ||
    err?.message ||
    err?.response?.data?.message ||
    err?.response?.data?.error?.message ||
    (typeof err?.response?.data?.error === 'string' ? err.response.data.error : '') ||
    fallback
  );
}
